UPDATE user_profile
SET access_token = #{accessToken},
    refresh_token = #{refreshToken},
    access_token_expires_at = #{accessTokenExpiresAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{profileId}
  AND deleted_at IS NULL

UPDATE user_profile
SET access_token = #{accessToken},
    access_token_expires_at = #{accessTokenExpiresAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{profileId}
  AND deleted_at IS NULL

UPDATE user_profile
SET password_failed_attempts = #{failedAttempts},
    password_locked_until = #{lockedUntil, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{profileId}
  AND deleted_at IS NULL
